import{_ as a,o as i,c as n,a5 as t}from"./chunks/framework.C1a7WKBV.js";const E=JSON.parse('{"title":"AI 评测驱动开发","description":"用真实样本、分层评分、回归门禁和线上反馈替代“感觉更好”，持续改进 AI 功能。","frontmatter":{"title":"AI 评测驱动开发","description":"用真实样本、分层评分、回归门禁和线上反馈替代“感觉更好”，持续改进 AI 功能。"},"headers":[],"relativePath":"development/evaluation-driven-development.md","filePath":"development/evaluation-driven-development.md","lastUpdated":1788838685000}'),l={name:"development/evaluation-driven-development.md"};function e(p,s,h,k,r,d){return i(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="ai-评测驱动开发" tabindex="-1">AI 评测驱动开发 <a class="header-anchor" href="#ai-评测驱动开发" aria-label="Permalink to &quot;AI 评测驱动开发&quot;">​</a></h1><p>传统程序对同一输入通常给出相同输出，AI 系统却可能用不同措辞得到同样正确的答案，也可能流畅地犯错。因此测试不能只比较字符串；但“无法精确断言”也不等于只能靠感觉。评测驱动开发的目标，是把产品期望变成一组可重复运行的证据。</p><h2 id="_1-从任务定义而不是模型分数开始" tabindex="-1">1. 从任务定义而不是模型分数开始 <a class="header-anchor" href="#_1-从任务定义而不是模型分数开始" aria-label="Permalink to &quot;1. 从任务定义而不是模型分数开始&quot;">​</a></h2><p>先写清三件事：</p><ol><li>用户想完成什么任务；</li><li>哪些失败绝对不能发生；</li><li>什么指标代表业务改善。</li></ol><p>以客服草稿为例：任务不是“写一段好回复”，而是“基于当前政策生成可发送的草稿”。硬约束包括不编造退款资格、不泄露内部字段、不擅自承诺补偿；业务指标可能是采纳率、编辑距离和平均处理时长。</p><h2 id="_2-建立有代表性的数据集" tabindex="-1">2. 建立有代表性的数据集 <a class="header-anchor" href="#_2-建立有代表性的数据集" aria-label="Permalink to &quot;2. 建立有代表性的数据集&quot;">​</a></h2><h3 id="_2-1-样本结构" tabindex="-1">2.1 样本结构 <a class="header-anchor" href="#_2-1-样本结构" aria-label="Permalink to &quot;2.1 样本结构&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ticket-0042&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;input&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;扣了两次款怎么办&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;plan&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pro&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;context&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;policy:duplicate-charge:v3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expected&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;intent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;duplicate_charge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;must_include&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;核对订单&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;退款处理时限&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;must_not_include&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;保证当天到账&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;slice&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;billing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;short-query&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;high-risk&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>数据集应来自脱敏的真实流量，而不是全由开发者凭空编写。每条样本带切片标签，才能发现总体分上升但“高风险计费问题”退步。</p><h3 id="_2-2-至少覆盖四类样本" tabindex="-1">2.2 至少覆盖四类样本 <a class="header-anchor" href="#_2-2-至少覆盖四类样本" aria-label="Permalink to &quot;2.2 至少覆盖四类样本&quot;">​</a></h3><ul><li>高频正常路径；</li><li>长尾与模糊输入；</li><li>对抗输入、越权请求和提示词注入；</li><li>无答案、工具失败、超预算等系统边界。</li></ul><p>初期几十条高质量样本胜过几千条含糊样本。线上出现一次重要失败，就把它清洗后加入回归集。</p><h2 id="_3-分层评分-不追求一个万能分数" tabindex="-1">3. 分层评分，不追求一个万能分数 <a class="header-anchor" href="#_3-分层评分-不追求一个万能分数" aria-label="Permalink to &quot;3. 分层评分，不追求一个万能分数&quot;">​</a></h2><h3 id="_3-1-确定性检查优先" tabindex="-1">3.1 确定性检查优先 <a class="header-anchor" href="#_3-1-确定性检查优先" aria-label="Permalink to &quot;3.1 确定性检查优先&quot;">​</a></h3><p>能用代码判断的不要交给另一个模型：JSON 是否可解析、字段是否齐全、链接是否属于允许域名、引用是否来自上下文、工具参数是否越权、总费用是否超限。</p><h3 id="_3-2-规则与参考答案" tabindex="-1">3.2 规则与参考答案 <a class="header-anchor" href="#_3-2-规则与参考答案" aria-label="Permalink to &quot;3.2 规则与参考答案&quot;">​</a></h3><p>分类任务可算准确率、精确率和召回率；信息抽取可按字段计算 F1；检索可用 Recall@K；代码任务应运行测试、类型检查和静态分析。</p><h3 id="_3-3-模型评分器" tabindex="-1">3.3 模型评分器 <a class="header-anchor" href="#_3-3-模型评分器" aria-label="Permalink to &quot;3.3 模型评分器&quot;">​</a></h3><p>语气、完整性、主张是否被证据支持等开放指标可用模型评分，但必须提供清晰量表：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事实忠实度：</span></span>
<span class="line"><span>4 = 所有关键主张均被给定证据直接支持</span></span>
<span class="line"><span>3 = 结论正确，有轻微无关扩展</span></span>
<span class="line"><span>2 = 至少一个次要主张缺少支持</span></span>
<span class="line"><span>1 = 核心结论缺少支持或与证据冲突</span></span>
<span class="line"><span>0 = 泄露信息、编造关键政策或未回答</span></span></code></pre></div><p>对评分器做校准：抽样由两位人工独立评分，比较模型与人工的一致性；对不一致案例改量表或拆指标。评分模型本身升级时也要重新校准。</p><h2 id="_4-区分组件评测与端到端评测" tabindex="-1">4. 区分组件评测与端到端评测 <a class="header-anchor" href="#_4-区分组件评测与端到端评测" aria-label="Permalink to &quot;4. 区分组件评测与端到端评测&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 → 检索 → 规划 → 工具 → 生成 → 输出</span></span></code></pre></div><p>端到端失败不告诉你哪一层坏了。需要分别测：</p><ul><li>查询改写是否保留意图；</li><li>检索是否取回标注证据；</li><li>工具选择与参数是否正确；</li><li>给定正确证据后，模型是否生成正确回答；</li><li>完整系统能否在预算内完成任务。</li></ul><p>组件评测用于快速定位，端到端评测用于验证真实体验，两者不可互相替代。</p><h2 id="_5-让每次改动都经过实验" tabindex="-1">5. 让每次改动都经过实验 <a class="header-anchor" href="#_5-让每次改动都经过实验" aria-label="Permalink to &quot;5. 让每次改动都经过实验&quot;">​</a></h2><p>记录实验清单：代码提交、提示模板版本、模型与参数、知识库版本、数据集版本、每个切片的指标、延迟和成本。</p><p>推荐比较规则：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>候选版本可以发布，当且仅当：</span></span>
<span class="line"><span>- 所有硬约束通过率 = 100%；</span></span>
<span class="line"><span>- 总体任务成功率不低于基线；</span></span>
<span class="line"><span>- 任一关键切片下降不超过阈值；</span></span>
<span class="line"><span>- P95 延迟与每成功任务成本在预算内；</span></span>
<span class="line"><span>- 人工抽检没有发现新的严重失败模式。</span></span></code></pre></div><p>不要只报“平均分提高 2%”。如果变化小于评分噪声，就不能证明候选更好。可用成对比较：让评分器在同一输入上盲选 A/B，再对胜负和分歧做人工抽检。</p><h2 id="_6-ci-中的评测门禁" tabindex="-1">6. CI 中的评测门禁 <a class="header-anchor" href="#_6-ci-中的评测门禁" aria-label="Permalink to &quot;6. CI 中的评测门禁&quot;">​</a></h2><p>小型稳定回归集放入每次提交的 CI；完整评测集在合并、模型切换或提示词发布前运行；昂贵的端到端 Agent 评测可按夜间任务运行。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">steps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">npm test</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">npm run eval:smoke</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">npm run eval:safety</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">npm run eval:report</span></span></code></pre></div><p>评测代码应能固定随机种子或保存原始输出，并设置并发与费用上限。失败报告必须显示具体样本、轨迹和评分理由，只有一个红色总分无法调试。</p><h2 id="_7-线上观测补足离线盲区" tabindex="-1">7. 线上观测补足离线盲区 <a class="header-anchor" href="#_7-线上观测补足离线盲区" aria-label="Permalink to &quot;7. 线上观测补足离线盲区&quot;">​</a></h2><p>离线集永远落后于真实世界。线上关注：完成率、用户重新提问率、草稿采纳率、人工接管率、错误类别、工具失败率、延迟、成本与安全事件。把负反馈与轨迹关联，区分“模型答错”“检索没找到”“工具执行失败”和“产品交互让用户误解”。</p><p>灰度发布时只给小比例流量，预先写清回滚阈值。不要在发现指标下降后才临时决定什么算严重。</p><h2 id="_8-避免评测系统自欺" tabindex="-1">8. 避免评测系统自欺 <a class="header-anchor" href="#_8-避免评测系统自欺" aria-label="Permalink to &quot;8. 避免评测系统自欺&quot;">​</a></h2><ul><li>不要用测试集持续调提示词而不保留隐藏集，否则会过拟合。</li><li>不要只测试容易自动评分的任务，忽略真正影响用户的复杂场景。</li><li>不要让生成答案和评分答案使用完全相同的错误假设。</li><li>不要把“风格更像标准答案”误当成“事实更正确”。</li><li>不要只评价最终文本；Agent 可能靠危险步骤碰巧得到正确答案。</li></ul><p>成熟团队讨论的不是“哪个模型最好”，而是“在我们的任务、数据、约束和预算下，哪个系统版本有证据更好”。</p>`,42)])])}const c=a(l,[["render",e]]);export{E as __pageData,c as default};
